with valid_employees as (select * from employees where salary > 62000 and (salary <= 113000 or hire_date <= '2024-10-29')), is_remote_summary as (select is_remote, max(hire_date) as last_hire_date, concat_ws(', ', sort_array(collect_set(level))) as level_values from valid_employees group by is_remote) select is_remote, last_hire_date from is_remote_summary order by last_hire_date, is_remote limit 5
